             a1 a2' a3' a4' a5' a6' a7' s2 (Z_to_bv 64 0) (Z_to_bv 64 TR_INIT) (Z_to_bv 64 k) (Z_to_bv 64 0) (Z_to_bv 64 TR_M2) s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xf9fac) fc None m (seg_rom asegs)).
